// Get the profile data from either direct payload or nested profileData
const profile = $json.body?.profileData || $json.body || $json;

const studentData = {
  personalInfo: {
    name: profile?.name || "",
    email: profile?.email || "",
    phone: profile?.phone || "",
    address: profile?.address || "",
    linkedin: profile?.linkedin || ""
  },
  academics: {
    age: profile?.age || 18,
    educationLevel: profile?.education_level || profile?.educationLevel || "",
    gradingSystem: profile?.grading_system || profile?.gradingSystem || "",
    academicScore: profile?.academic_score || profile?.academicScore || 0,
    standardizedTest: profile?.standardized_test || profile?.standardizedTest || "none",
    testScore: profile?.test_score || profile?.testScore || 0
  },
  preferences: {
    targetCountries: profile?.target_countries || profile?.targetCountries || [],
    studyLevel: profile?.study_level || profile?.studyLevel || "",
    budgetMin: profile?.budget_min || profile?.budgetMin || 20000,
    budgetMax: profile?.budget_max || profile?.budgetMax || 80000,
    scholarshipInterest: profile?.scholarship_interest || profile?.scholarshipInterest || false,
    subjects: profile?.subjects || [],
    extracurriculars: profile?.extracurriculars || [],
    careerGoals: profile?.career_goals || profile?.careerGoals || ""
  },
  experience: {
    organization: profile?.organization || "",
    designation: profile?.designation || "",
    bio: profile?.bio || "",
    skills: profile?.skills || []
  }
};

return { studentData };

const parts = $json.candidates?.[0]?.content?.parts || [];
const raw = parts.map(p => p.text || "").join("\n");

function between(a, b) {
  const i = raw.indexOf(a);
  const j = raw.indexOf(b);
  if (i === -1 || j === -1 || j <= i) return "";
  return raw.slice(i + a.length, j).trim();
}

const counselorMessage = between("<<<COUNSELOR_MESSAGE_START>>>", "<<<COUNSELOR_MESSAGE_END>>>") || "Thank you for sharing your profile! We're analyzing your academic background and preferences to identify the best university matches for you.";
const jsonBlock = between("<<<RECOMMENDATIONS_JSON_START>>>", "<<<RECOMMENDATIONS_JSON_END>>>");

let recs = { safe: [], target: [], dream: [] };

// Try to parse JSON
if (jsonBlock && jsonBlock.length > 0) {
  try {
    const parsed = JSON.parse(jsonBlock);
    if (parsed && typeof parsed === 'object') {
      recs.safe = Array.isArray(parsed.safe) ? parsed.safe.slice(0, 4) : [];
      recs.target = Array.isArray(parsed.target) ? parsed.target.slice(0, 4) : [];
      recs.dream = Array.isArray(parsed.dream) ? parsed.dream.slice(0, 3) : [];
    }
  } catch (e) {
    // JSON parse failed, use defaults below
  }
}

// Fallback to sample universities if parsing failed
if (!recs.safe || recs.safe.length === 0) {
  recs = {
    safe: [
      { name: "University of Toronto", city: "Toronto", country: "Canada", score: 85, acceptance_rate: 20, est_tuition_usd: 15000, program_fit: "Strong match for your profile", rationale: "Budget-friendly with strong academics", notes: "Excellent engineering program" },
      { name: "University of British Columbia", city: "Vancouver", country: "Canada", score: 82, acceptance_rate: 23, est_tuition_usd: 16000, program_fit: "Solid academic alignment", rationale: "Within budget range", notes: "Great international support" },
      { name: "McGill University", city: "Montreal", country: "Canada", score: 81, acceptance_rate: 24, est_tuition_usd: 14000, program_fit: "Good academic fit", rationale: "Affordable option in major city", notes: "Diverse student body" }
    ],
    target: [
      { name: "University of California, Berkeley", city: "Berkeley", country: "USA", score: 78, acceptance_rate: 15, est_tuition_usd: 45000, program_fit: "Challenging but achievable", rationale: "Top-tier program in your field", notes: "Scholarship opportunities available" },
      { name: "Imperial College London", city: "London", country: "UK", score: 75, acceptance_rate: 8, est_tuition_usd: 38000, program_fit: "High academic demand", rationale: "World-leading research", notes: "International student support strong" },
      { name: "National University of Singapore", city: "Singapore", country: "Singapore", score: 76, acceptance_rate: 25, est_tuition_usd: 23000, program_fit: "Strong technical programs", rationale: "Hub for innovation in Asia", notes: "Competitive scholarships for international students" }
    ],
    dream: [
      { name: "MIT", city: "Cambridge", country: "USA", score: 70, acceptance_rate: 4, est_tuition_usd: 62000, program_fit: "Highly competitive", rationale: "Leading innovation hub", notes: "Strong merit scholarships" },
      { name: "Stanford University", city: "Stanford", country: "USA", score: 72, acceptance_rate: 3, est_tuition_usd: 60000, program_fit: "Exceptional opportunity", rationale: "Elite research and technology", notes: "Access to Silicon Valley" }
    ]
  };
}

return {
  counselorMessage,
  matchedUniversities: recs,
};

const data = $json.studentData;
const message = $json.counselorMessage || "No message available.";
const matches = $json.matchedUniversities || { safe: [], target: [], dream: [] };

const currencyFmt = (n) => (n || n === 0) ? `$${Number(n).toLocaleString()}` : "N/A";

const formatUni = (u) => `
  <li style="padding: 15px; margin: 10px 0; background: white; border-left: 4px solid #667eea; border-radius: 4px;">
    <strong>${u.name}</strong><br>
    📍 ${u.city}, ${u.country}<br>
    ✨ Match Score: ${u.score}/100 | Acceptance: ${u.acceptance_rate}%<br>
    💵 Est. Tuition: ${currencyFmt(u.est_tuition_usd)}<br>
    🎓 Fit: ${u.program_fit}<br>
    🧭 Why: ${u.rationale}${u.notes ? `<br>📝 Notes: ${u.notes}` : ""}
  </li>
`;

const renderList = (arr) => `<ul style="list-style: none; padding: 0;">${(arr || []).map(formatUni).join("") || "<li>No matches available.</li>"}</ul>`;

const emailBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, sans-serif; color: #333; background: #f0f2f8; }
    .container { max-width: 720px; margin: 0 auto; background: white; box-shadow: 0 8px 24px rgba(0,0,0,0.08); border-radius: 8px; overflow: hidden; }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 36px 24px; text-align: center; }
    .content { padding: 28px 24px; }
    .section { margin-bottom: 28px; }
    .message-box { background: #f9f9ff; border-left: 4px solid #667eea; padding: 16px; margin-top: 10px; line-height: 1.6; white-space: pre-wrap; }
    h2 { margin-bottom: 8px; }
    .footer { background: #f5f5f7; padding: 18px; text-align: center; font-size: 12px; color: #666; border-top: 1px solid #ececec; }
    .pill { display: inline-block; background: #eef; color: #334; padding: 4px 10px; border-radius: 999px; font-size: 12px; margin-right: 6px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🎓 Your University Counselor Report</h1>
      <p>Welcome${data.personalInfo.name ? ", " + data.personalInfo.name : ""}! Here's your personalized guidance.</p>
      <div>
        ${data.preferences.targetCountries?.map(c=>`<span class="pill">${c}</span>`).join("") || ""}
        ${data.preferences.subjects?.map(s=>`<span class="pill">${s}</span>`).join("") || ""}
      </div>
    </div>
    <div class="content">
      <div class="section">
        <h2>📚 Counselor's Message</h2>
        <div class="message-box">${message}</div>
      </div>

      <div class="section">
        <h2>🎯 Your Matched Universities</h2>

        <h3>🔒 Safe Universities</h3>
        ${renderList(matches.safe)}

        <h3>🎯 Target Universities</h3>
        ${renderList(matches.target)}

        <h3>⭐ Dream Universities</h3>
        ${renderList(matches.dream)}
      </div>
    </div>

    <div class="footer">
      <p>Match Maker Path Student Counselor</p>
    </div>
  </div>
</body>
</html>
`;

return { emailBody };
